<?php
if(!defined('ABSPATH')){exit;}
final class Orion_AI_Provider_Factory{
 public static function create(array $settings,string $stage='answer'):Orion_AI_Provider{$primary_provider=Orion_AI_Settings::provider($settings);$primary_model=Orion_AI_Settings::stage_model($settings,$stage,$primary_provider);$timeout=Orion_AI_Settings::stage_timeout($settings,$stage);$max_tokens=match($stage){'answer'=>1400,'routing'=>1200,default=>900};$primary=self::raw($primary_provider,$primary_model,$timeout,$max_tokens,$settings);$fallback_provider=(string)($settings['fallback_provider']??'none');$fallback=null;if(in_array($fallback_provider,array('openrouter','google'),true)&&Orion_AI_Settings::key_configured($fallback_provider,$settings)){$fallback_model=trim((string)($settings['fallback_model']??''));if($fallback_model==='')$fallback_model='google'===$fallback_provider?(string)($settings['google_model']??'gemini-2.5-flash'):(string)($settings['openrouter_model']??'openrouter/free');if($fallback_provider!==$primary_provider||$fallback_model!==$primary_model)$fallback=self::raw($fallback_provider,$fallback_model,$timeout,$max_tokens,$settings);}return new Orion_Resilient_Provider($primary,$fallback,$stage);}
 private static function raw(string $provider,string $model,int $timeout,int $max_tokens,array $settings):Orion_AI_Provider{return'google'===$provider?new Orion_Gemini_Client(Orion_AI_Settings::google_key($settings),$model,$timeout,$max_tokens):new Orion_OpenRouter_Client(Orion_AI_Settings::openrouter_key($settings),$model,$timeout,$max_tokens);}
}
